def fetch_all(database_id):
  out=[]
  r,_=run_composio_tool('NOTION_QUERY_DATABASE',{'database_id':database_id,'page_size':100})
  d=(r or {}).get('data') or {}
  out+=d.get('results') or []
  while d.get('has_more') and d.get('next_cursor'):
    r,_=run_composio_tool('NOTION_QUERY_DATABASE',{'database_id':database_id,'start_cursor':d['next_cursor'],'page_size':100})
    d=(r or {}).get('data') or {}
    out+=d.get('results') or []
  return out
