def get_title(item):
  props=(item or {}).get('properties') or {}
  for v in props.values():
    if isinstance(v,dict) and v.get('type')=='title':
      parts=v.get('title') or []
      return ''.join((p or {}).get('plain_text','') for p in parts if isinstance(p,dict)).strip()
  return ''
